import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function SellerLogin({ onClose }) {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [showPassword, setShowPassword] = useState(false);
    const [step, setStep] = useState(1); // 1: email check, 2: password entry, 3: set password
    const [sellerInfo, setSellerInfo] = useState(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        // Initialize icons if lucide is available
        if (window.lucide) {
            window.lucide.createIcons();
        }
    }, []);

    const handleEmailSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email) {
            toast.error('Please enter your email');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email: loginData.email })
            });
            
            const data = await response.json();
            
            if (data.success) {
                if (data.needsPassword) {
                    setSellerInfo(data.data);
                    if (data.data && data.data.needsPasswordSetup) {
                        setStep(3); // Set password
                    } else {
                        setStep(2); // Enter password
                    }
                } else {
                    // Login successful, store user data and redirect
                    localStorage.setItem('studioToken', 'simulated-token');
                    localStorage.setItem('studioUser', JSON.stringify({
                        id: data.data.id,
                        email: data.data.email,
                        firstName: data.data.firstname,
                        lastName: data.data.lastname,
                        role: 'seller'
                    }));
                    toast.success('Login successful');
                    if (onClose) onClose();
                    navigate('/studio/seller');
                }
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter your password');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login-with-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                // Login successful, store user data and redirect
                localStorage.setItem('studioToken', 'simulated-token');
                localStorage.setItem('studioUser', JSON.stringify({
                    id: data.data.id,
                    email: data.data.email,
                    firstName: data.data.firstname,
                    lastName: data.data.lastname,
                    role: 'seller'
                }));
                toast.success('Login successful');
                if (onClose) onClose();
                navigate('/studio/seller');
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleSetPasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter a password');
            return;
        }

        if (loginData.password.length < 6) {
            toast.error('Password must be at least 6 characters long');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/set-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                toast.success('Password set successfully. Please login with your password.');
                setStep(2); // Go to password entry step
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Set password error:', error);
            toast.error('Failed to set password: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const renderEmailForm = () => (
        <form onSubmit={handleEmailSubmit} className="authentication-form">
            <div className="mb-4">
                <label className="form-label" htmlFor="UserEmail">Email</label>
                <div className="position-relative w-100">
                    <input 
                        type="email" 
                        className="form-control form-control-lg rounded" 
                        id="UserEmail" 
                        name="email"
                        placeholder="Enter your email" 
                        value={loginData.email}
                        onChange={(e) => setLoginData({...loginData, email: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <p className="text-muted p-0 position-absolute end-0 top-50 border-0 fs-4 translate-middle-y me-2 mb-0">
                        <iconify-icon icon="solar:letter-bold-duotone" className="fs-20 mt-1 text-muted"></iconify-icon>
                    </p>
                </div>
            </div>
            <div className="text-center d-grid">
                <button 
                    className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Checking...
                        </>
                    ) : (
                        <>
                            <i data-lucide="arrow-right" className="fs-18"></i> Continue
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    const renderPasswordForm = () => (
        <form onSubmit={handlePasswordSubmit} className="authentication-form">
            <div className="mb-4">
                <a href="#" className="float-end fw-semibold text-reset ms-1">Reset password</a>
                <label className="form-label" htmlFor="UserPass">Password</label>
                <div className="position-relative w-100">
                    <input 
                        type={showPassword ? "text" : "password"}
                        className="form-control form-control-lg rounded" 
                        id="UserPass" 
                        name="password"
                        placeholder="Enter your password" 
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <button
                        type="button"
                        className="btn text-muted p-0 position-absolute end-0 top-50 border-0 fs-4 translate-middle-y me-2"
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        <iconify-icon
                            icon={showPassword ? "solar:eye-closed-bold-duotone" : "solar:eye-bold-duotone"}
                            className="fs-20 mt-1 text-muted"
                        ></iconify-icon>
                    </button>
                </div>
            </div>
            <div className="text-center d-grid">
                <button 
                    className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Signing in...
                        </>
                    ) : (
                        <>
                            <i data-lucide="log-in" className="fs-18"></i> Sign In
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    const renderSetPasswordForm = () => (
        <form onSubmit={handleSetPasswordSubmit} className="authentication-form">
            <div className="alert alert-info">
                <p className="mb-0">
                    <i className="ri-information-line me-1"></i>
                    Welcome! Please set your password to complete your seller account setup.
                </p>
            </div>
            
            <div className="mb-4">
                <label className="form-label" htmlFor="newPassword">New Password</label>
                <div className="position-relative w-100">
                    <input 
                        type={showPassword ? "text" : "password"}
                        className="form-control form-control-lg rounded" 
                        id="newPassword" 
                        name="password"
                        placeholder="Enter your new password" 
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <button
                        type="button"
                        className="btn text-muted p-0 position-absolute end-0 top-50 border-0 fs-4 translate-middle-y me-2"
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        <iconify-icon
                            icon={showPassword ? "solar:eye-closed-bold-duotone" : "solar:eye-bold-duotone"}
                            className="fs-20 mt-1 text-muted"
                        ></iconify-icon>
                    </button>
                </div>
                <div className="form-text">Password must be at least 6 characters long</div>
            </div>
            <div className="text-center d-grid">
                <button 
                    className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Setting Password...
                        </>
                    ) : (
                        <>
                            <i data-lucide="check" className="fs-18"></i> Set Password
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    return (
        <div className="auth-page-wrapper">
            <div className="container">
                <div className="row justify-content-center">
                    <div className="col-lg-12">
                        <div className="text-center mt-sm-5 mb-4">
                            <h3 className="fw-bold text-dark">Seller Login</h3>
                            <p className="text-muted">
                                {step === 1 && "Enter your email to verify your seller account"}
                                {step === 2 && "Enter your password to login"}
                                {step === 3 && "Set your password to complete setup"}
                            </p>
                        </div>
                    </div>
                </div>

                <div className="row justify-content-center">
                    <div className="col-xl-8">
                        <div className="card">
                            <div className="card-body">
                                <div className="p-3">
                                    {step === 1 && renderEmailForm()}
                                    {step === 2 && renderPasswordForm()}
                                    {step === 3 && renderSetPasswordForm()}
                                    
                                    {step > 1 && (
                                        <div className="mt-3 text-center">
                                            <button 
                                                className="btn btn-link text-primary text-decoration-underline p-0"
                                                onClick={() => setStep(1)}
                                                disabled={loading}
                                            >
                                                <i className="ri-arrow-left-line me-1"></i>
                                                Back to Email Verification
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                        
                        <div className="mt-4 text-center">
                            <p className="mb-0">
                                Don't have an account?{' '}
                                <button 
                                    className="btn btn-link p-0 text-primary text-decoration-underline"
                                    onClick={() => {
                                        if (onClose) onClose();
                                        navigate('/studio');
                                    }}
                                >
                                    Apply for access
                                </button>
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
